<?php require_once __DIR__ . '/auth.php'; require_login('admin');$id=(int)($_GET['id']??0);$student=one('SELECT u.*,s.* FROM users u JOIN students s ON s.user_id=u.id WHERE u.id=?','i',[$id]);if(!$student)redirect('students.php');$pageTitle='Student profile';include 'includes/header.php';?><div class="page-head"><div><div class="eyebrow">Student profile</div><h1><?=e($student['name'])?></h1><p><?=e($student['course'])?> · <?=e($student['university'])?></p></div><a class="button button-quiet" href="students.php">← All students</a></div><section class="panel"><div class="stat-grid"><div class="stat-card"><small>Semester</small><strong style="font-size:1.3rem"><?=e($student['semester'])?></strong></div><div class="stat-card"><small>Email</small><strong style="font-size:1rem"><?=e($student['email'])?></strong></div><div class="stat-card"><small>Account</small><strong style="font-size:1.3rem">Active</strong></div></div></section><?php include 'includes/footer.php';?>